package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamFitnessBank2 {
    private const val T = "ශාරීරික යෝග්‍යතාව, යෝග්‍යතා පරීක්ෂණ හා පුහුණු මූලධර්ම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("කෙටි දුර ධාවනයේදී (මීටර් 100) හෝ ක්ෂණික පිම්මකදී පළමු තත්පර 8-10 තුළ ඔක්සිජන් රහිතව ක්ෂණික ශක්තිය සපයන ප්‍රධාන ශක්ති පද්ධතිය කුමක්ද?", "ATP-PCr (පොස්ෆොක්‍රියටීන්) පද්ධතිය", "ලැක්ටික් අම්ල පද්ධතිය", "සවායු පද්ධතිය", "ලිපිඩ ඔක්සිකරණ පද්ධතිය", "පේශි තුළ ගබඩා වී ඇති ඇඩිනොසින් ට්‍රයිපොස්පේට් සහ පොස්ෆොක්‍රියටීන් මගින් ක්ෂණික පුපුරන සුලු බලයක් ලබා දෙයි."),
        q("තත්පර 10 සිට මිනිත්තු 2ක් පමණ දක්වා පවතින දැඩි තීව්‍රතාවයේ ව්‍යායාමවලදී (උදා. මීටර් 400 ධාවනය) ක්‍රියාත්මක වන ප්‍රධාන නිර්වායු ශක්ති පද්ධතිය කුමක්ද?", "ලැක්ටික් අම්ල පද්ධතිය හෙවත් නිර්වායු ග්ලයිකොලිසිය", "ATP-PCr පද්ධතිය", "සවායු පද්ධතිය", "මේද දහන පද්ධතිය", "ග්ලූකෝස් නිර්වායු ලෙස අසම්පූර්ණව බිඳහෙළීමෙන් ලැක්ටික් අම්ලය හා ATP නිපදවනු ලබයි."),
        q("මිනිත්තු කිහිපයක සිට පැය ගණනක් පුරා විඳදරාගැනීමේ ක්‍රීඩාවලදී (උදා. මැරතන්) කාබෝහයිඩ්‍රේට් හා මේද ඔක්සිජන් හමුවේ දහනය කරන ශක්ති පද්ධතිය කුමක්ද?", "සවායු ශක්ති පද්ධතිය (Aerobic System)", "ATP-PCr පද්ධතිය", "ලැක්ටික් අම්ල පද්ධතිය", "ක්ෂණික පද්ධතිය", "සෛලයේ මයිටොකොන්ඩ්‍රියා තුළදී විශාල ATP ප්‍රමාණයක් කාබන් ඩයොක්සයිඩ් හා ජලය අතුරු ඵල ලෙස නිපදවයි."),
        q("ක්‍රීඩකයෙකුගේ ව්‍යායාම තීව්‍රතාව වැඩි වන විට රුධිරයේ ලැක්ටික් අම්ලය ශීඝ්‍රයෙන් එකතු වීමට පටන් ගන්නා තීරණාත්මක සීමාව කුමක්ද?", "ලැක්ටේට් සීමාව හෙවත් නිර්වායු සීමාව (Lactate Threshold)", "සවායු සීමාව", "උපරිම හෘද ස්පන්දනය", "විවේකී සීමාව", "ලැක්ටේට් සීමාව පසු වූ විට ශරීරයට ලැක්ටික් අම්ලය ඉවත් කිරීමට වඩා වේගයෙන් එය එකතු වීම නිසා පේශි අඩපණ වේ."),
        q("අත්වල ග්‍රහණ ශක්තිය (Handgrip Strength) නිරවද්‍යව මැනීම සඳහා භාවිත කරන විශේෂිත උපකරණය කුමක්ද?", "අත් ග්‍රහණ ඩයිනමෝමීටරය (Handgrip Dynamometer)", "ස්පයිරෝමීටරය", "ස්කින්ෆෝල්ඩ් කැලිපරය", "ගෝනියෝමීටරය", "අත්ලෙන් උපරිම බලය යොදා තද කිරීමෙන් ලැබෙන කිලෝග්‍රෑම් අගය මගින් පේශි ශක්තිය තක්සේරු කරයි."),
        q("ශරීරයේ සන්ධියක සම්පූර්ණ කෝණික චලන පරාසය (චලන කෝණය) අංශකවලින් මැනීමට යොදාගන්නා උපකරණය කුමක්ද?", "ගෝනියෝමීටරය (Goniometer)", "ඩයිනමෝමීටරය", "ස්ෆිග්මෝමනෝමීටරය", "ස්ටෙතස්කෝපය", "ගෝනියෝමීටරය සන්ධිය මත තබා නැමීමේ සහ දිගහැරීමේ උපරිම කෝණය අංශකවලින් මනිනු ලබයි."),
        q("ඉදිරියට දිවීම, දෙපසට පියවර තැබීම (Shuffle) සහ පසුපසට දිවීම ඇතුළත් කඩිසරතාව මනින 'T' හැඩැති පරීක්ෂණය කුමක්ද?", "T-කඩිසරතා පරීක්ෂණය (T-Test)", "ෂටල් ධාවනය", "බීප් පරීක්ෂණය", "ස්ටෝක් පරීක්ෂණය", "කේතු 4ක් T හැඩයට තබා විවිධ දිශාවලට ශීඝ්‍රයෙන් චලනය වීමේ හැකියාව තත්පරවලින් මනියි."),
        q("උරහිස් සන්ධිවල නම්‍යශීලීතාව මැනීම සඳහා එක් අතක් උරහිසට ඉහළින්ද අනෙක් අත පිටුපසින් පහළින්ද යවා ඇඟිලි එකිනෙක ස්පර්ශ කිරීමේ පරීක්ෂණය කුමක්ද?", "උරහිස් නම්‍යශීලීතා පරීක්ෂණය (Shoulder Stretch Test)", "සිට් ඇන්ඩ් රීච්", "ට්‍රන්ක් ලිෆ්ට්", "සාජන්ට් පරීක්ෂණය", "දෑතේ ඇඟිලි එකිනෙක අතිච්ඡාදනය වන ප්‍රමාණය හෝ පරතරය සෙන්ටිමීටරවලින් මැන නම්‍යශීලීතාව දක්වයි."),
        q("බඩ මත වැතිර දෑත් පිටුපසට තබා පපුව බිමෙන් ඉහළට එසවීමෙන් කොඳු ඇට පෙළ විස්තාරක පේශිවල නම්‍යශීලීතාව මනින පරීක්ෂණය කුමක්ද?", "උඩුකය එසවීමේ පරීක්ෂණය (Trunk Lift Test)", "සිට් ඇන්ඩ් රීච්", "කර්ල්-අප්ස්", "පුෂ්-අප්ස්", "ගෙල හා පපුව බිම සිට සෙන්ටිමීටර කීයක් ඉහළට එසවිය හැකිදැයි මැන බැලීම සිදු කරයි."),
        q("බර පුහුණුවේදී මාංශපේශී ප්‍රමාණය විශාල කර ගැනීම (Muscle Hypertrophy) සඳහා වඩාත් යෝග්‍ය පුනරාවර්තන (Reps) පරාසය කුමක්ද?", "මධ්‍යම බරකින් පුනරාවර්තන 8 සිට 12 දක්වා", "උපරිම බරකින් පුනරාවර්තන 1 සිට 3 දක්වා", "ඉතා අඩු බරකින් පුනරාවර්තන 50ක්", "පුනරාවර්තන 100ක්", "පුනරාවර්තන 8-12 සහ කට්ටල 3-4 ක් සිදුකිරීම මගින් පේශි කෙඳිවල ප්‍රමාණය උපරිම ලෙස වර්ධනය වේ."),
        q("බර පුහුණුවේදී එක දිගට සිදුකරන පුනරාවර්තන (Reps) සමූහයක් එක්ව හඳුන්වන නම කුමක්ද?", "කට්ටලයක් (Set)", "වාරයක්", "චක්‍රයක්", "සැසියක්", "උදාහරණයක් ලෙස පුෂ්-අප්ස් 15ක් එක දිගට සිදුකිරීම එක් කට්ටලයක් (One Set) ලෙස සැලකේ."),
        q("බර පුහුණුවේදී කට්ටල දෙකක් අතර ලබාගත යුතු සාමාන්‍ය සුදුසු විවේක කාලය කොපමණද?", "තත්පර 60 සිට මිනිත්තු 2ක් දක්වා", "තත්පර 5ක් පමණි", "පැය භාගයක්", "විවේක නොගත යුතුය", "තත්පර 60-120 ක විවේකය මගින් පේශිවල ATP සහ PCr සංචිත නැවත ගොඩනැගීමට ඉඩ සැලසේ."),
        q("බර පුහුණුවකදී 'පුහුණු පරිමාව' (Training Volume) ගණනය කරනු ලබන නිවැරදි සූත්‍රය කුමක්ද?", "ඔසවන ලද බර × පුනරාවර්තන ගණන × කට්ටල ගණන", "බර / කට්ටල ගණන", "කාලය × වේගය", "ස්පන්දන වේගය × බර", "පුහුණු පරිමාව මගින් එක් සැසියකදී පේශි මත යෙදූ සමස්ත වැඩ ප්‍රමාණය නිරූපණය වේ."),
        q("විවේකී හෘද ස්පන්දන වේගය (RHR) සැලකිල්ලට ගනිමින් ඉලක්කගත හෘද ස්පන්දනය ගණනය කරන 'කාර්වෝනන් සූත්‍රය' කුමක්ද?", "ඉලක්කගත HR = ((MHR — RHR) × %තීව්‍රතාව) + RHR", "ඉලක්කගත HR = MHR × %තීව්‍රතාව", "ඉලක්කගත HR = 220 — වයස", "ඉලක්කගත HR = RHR + වයස", "කාර්වෝනන් ක්‍රමය මගින් හෘද ස්පන්දන සංචිතය (Heart Rate Reserve) පදනම් කරගෙන වඩාත් නිවැරදි ඉලක්කයක් ලබා දෙයි."),
        q("ක්‍රීඩකයෙකුගේ උපරිම හෘද ස්පන්දනය (MHR) සහ විවේකී හෘද ස්පන්දනය (RHR) අතර පවතින වෙනස හඳුන්වන්නේ කෙසේද?", "හෘද ස්පන්දන සංචිතය (Heart Rate Reserve - HRR)", "පහර පරිමාව", "හෘද නිමැවුම", "රුධිර පීඩනය", "HRR මගින් පුද්ගලයාට ව්‍යායාමයේදී උපරිමව වැඩි කළ හැකි හෘද ස්පන්දන පරාසය දක්වයි."),
        q("ක්‍රීඩකයෙකු තම පෞද්ගලික ඉහළම ශක්තිය මැනීමට එක් වරකදී ඔසවිය හැකි උපරිම බර හඳුන්වන කෙටි යෙදුම කුමක්ද?", "1RM (One-Repetition Maximum)", "BMI", "VO2 max", "RPE", "1RM අගය පදනම් කරගෙන විවිධ පුහුණු අරමුණු සඳහා බර ප්‍රතිශතයක් ලෙස (උදා. 70% of 1RM) නියම කරයි."),
        q("ව්‍යායාමයකදී පුද්ගලයාට දැනෙන වෙහෙස ප්‍රමාණය 6 සිට 20 දක්වා හෝ 1 සිට 10 දක්වා අගයකින් ප්‍රකාශ කරන පරිමාණය කුමක්ද?", "බෝර්ග්ගේ ප්‍රත්‍යක්ෂ වෙහෙස පරිමාණය (RPE Scale)", "BMI පරිමාණය", "සෙන්ටිග්‍රේඩ් පරිමාණය", "ස්පයිරෝ පරිමාණය", "Rate of Perceived Exertion මගින් හෘද මොනිටරයක් නොමැති විටද ව්‍යායාම තීව්‍රතාව තක්සේරු කළ හැක."),
        q("දැඩි ව්‍යායාමයකින් පැය 24 සිට 48 දක්වා කාලයකදී මාංශපේශීවල ඇතිවන තදබව සහ වේදනාව (DOMS) හඳුන්වන්නේ කෙසේද?", "ප්‍රමාද වී හටගන්නා මාංශපේශී වේදනාව (Delayed Onset Muscle Soreness)", "ක්ෂණික කැක්කුම", "මාංශපේශී ඉරීම", "අස්ථි බිඳීම", "DOMS ඇතිවන්නේ පේශි කෙඳිවල සිදුවන ක්ෂුද්‍ර ඉරීම් සහ ප්‍රදාහය නිසා මිස ලැක්ටික් අම්ලය නිසා නොවේ."),
        q("ව්‍යායාමයකින් පසු ඇතිවන DOMS වේදනාව සමනය කර ගැනීමට උපකාරී වන ප්‍රායෝගික ක්‍රියාමාර්ගයක් කුමක්ද?", "සැහැල්ලු සක්‍රීය ඇවිදීම, ප්‍රමාණවත් ජලය පානය සහ මෘදු දිගැදුම්", "එක දිගට අධික බර එසවීම", "කිසිසේත් චලනය නොවී සිටීම", "උණුසුම් ආහාර පමණක් ගැනීම", "සැහැල්ලු චලනයන් මගින් රුධිර සංසරණය වැඩි කර පටක අලුත්වැඩියාව වේගවත් කරයි."),
        q("ශරීරයේ බර දරන ප්‍රධාන සන්ධි (දණහිස, වළලුකර) ආරක්ෂා කරගනිමින් වැඩිහිටියන්ට හෝ ආබාධ සහිත අයට සුදුසුම අඩු කම්පන සවායු ව්‍යායාමය කුමක්ද?", "පිහිනීම සහ ස්ථාවර පාපැදි පැදීම (Low-impact exercises)", "තාර පාරේ පැන පැන දිවීම", "ප්ලයොමෙට්‍රික් පිමි", "බර එසවීම", "ජලයේ ප්ලාව්‍යතාව නිසා සන්ධි මත ශරීර බර පැටවීමකින් තොරව හෘද ස්වසන යෝග්‍යතාව වර්ධනය වේ."),
        q("වැඩිහිටි වියේදී ඇදවැටීම් සහ අස්ථි බිඳීම් වළක්වා ගැනීම සඳහා විශේෂයෙන් පුහුණු කළ යුතු යෝග්‍යතා සංඝටක දෙක මොනවාද?", "සමබරතාව සහ මාංශපේශී ශක්තිය", "වේගය සහ ජවය පමණි", "කඩිසරතාව පමණි", "නම්‍යශීලීතාව පමණි", "පාදවල ශක්තිය හා සමබරතාව රැකගැනීමෙන් වැඩිහිටියන් ලිස්සා වැටීමෙන් සිදුවන උකුල් ඇට බිඳීම් වළකී."),
        q("නව යොවුන් වියේ පසුවන පාසල් දරුවන්ට බර පුහුණුව (Weight Training) ලබාදීමේදී අනුගමනය කළ යුතු ප්‍රධාන ආරක්ෂක නීතිය කුමක්ද?", "අධික බර එසවීමෙන් වැළකී නිවැරදි තාක්ෂණය සහ ශරීර බර යොදාගැනීමට මුල්තැන දීම", "උපරිම බර පමණක් එසවීමට දීම", "ආරක්ෂක උපදෙස් නොමැතිව තනිවම කිරීමට ඉඩදීම", "හුස්ම තද කරගෙන බර එසවීම", "අස්ථිවල වර්ධක තැටිවලට (Epiphyseal plates) හානි නොවීමට නම් අධික බර නොඑසවිය යුතුය."),
        q("යෝග්‍යතා සංවර්ධනයේදී 'ක්‍රොස් ට්‍රේනිං' (Cross-Training) යන්නෙන් අදහස් වන්නේ කුමක්ද?", "තම ප්‍රධාන ක්‍රීඩාවට අමතරව වෙනත් විවිධ ක්‍රීඩා හෝ ව්‍යායාම ක්‍රම පුහුණුවට ඇතුළත් කර ගැනීම", "එකම ව්‍යායාමය දිනපතා පැය ගණනක් කිරීම", "පුහුණුවීම් සම්පූර්ණයෙන් නැවැත්වීම", "තරගවලට පමණක් සහභාගී වීම", "උදාහරණයක් ලෙස ධාවකයෙකු පිහිනීම හෝ පාපැදි පැදීම මගින් විවිධ පේශි ශක්තිමත් කර ඒකාකාරී බව දුරු කරයි."),
        q("ව්‍යායාමයකදී මාංශපේශී දිගු වෙමින් ආතතිය රඳවා ගන්නා අදියර (උදා. බයිසෙප්ස් කර්ල් එකකදී බර පහළට බෑම) කුමක්ද?", "විමධ්‍යගත අදියර හෙවත් දිගුවීමේ අදියර (Eccentric Contraction)", "කේන්ද්‍රාභිසාරී අදියර", "සමමිතික අදියර", "ස්ථිතික අදියර", "Eccentric හැකිලීමේදී මාංශපේශී කෙඳිවලට වැඩි ආතතියක් ලැබෙන අතර පේශි වර්ධනයට එය බෙහෙවින් දායක වේ."),
        q("ව්‍යායාමයකදී මාංශපේශී කෙටි වෙමින් බලය යොදන අදියර (උදා. බර ඉහළට එසවීම) කුමක්ද?", "සමකේන්ද්‍රික අදියර හෙවත් කෙටිවීමේ අදියර (Concentric Contraction)", "විමධ්‍යගත අදියර", "ලිහිල් අදියර", "අක්‍රිය අදියර", "Concentric හැකිලීමේදී පේශිය කෙටි වී සන්ධිය නමමින් ප්‍රතිරෝධය ජය ගනී."),
        q("දිනපතා දිගු වේලාවක් වාඩි වී සිටින පරිගණක හා කාර්යාල සේවකයන්ගේ කෙටි වී තද වන ප්‍රධාන පේශි කාණ්ඩය කුමක්ද?", "ඉණ නවන පේශි (Hip Flexors) සහ පපුවේ පේශි", "කෙණ්ඩ පේශි", "උරහිස් පේශි", "පාද ඇඟිලි පේශි", "දිගු වේලාවක් වාඩිවී සිටීමෙන් ඉණ නවන පේශි කෙටි වී ලෝඩෝසිස් සහ යටිකොන්දේ වේදනාව හටගනී."),
        q("යටිකොන්දේ වේදනාව වළක්වා ගැනීම සඳහා ශක්තිමත් කළ යුතු ප්‍රධානතම ගැඹුරු උදරීය පේශිය කුමක්ද?", "තිරස් උදර පේශිය (Transverse Abdominis)", "සෘජු උදර පේශිය", "ඩෙල්ටොයිඩ් පේශිය", "ට්‍රැපීසියස් පේශිය", "Transverse abdominis පේශිය ස්වාභාවික බඳපටියක් (Corset) මෙන් ක්‍රියා කරමින් කොඳු ඇට පෙළ ස්ථාවර කරයි."),
        q("ශාරීරික යෝග්‍යතාවය වැඩිදියුණු වීමත් සමග රුධිර පීඩනය පාලනය වීමට හේතුවන ප්‍රධාන සාධකය කුමක්ද?", "රුධිර නාලවල ප්‍රත්‍යාස්ථතාව වැඩිවීම සහ රුධිර සංසරණ ප්‍රතිරෝධය අඩුවීම", "රුධිර නාල ඝන වීම", "හෘදය කුඩා වීම", "රුධිර පරිමාව අඩුවීම", "නිතිපතා ව්‍යායාම කිරීමෙන් ධමනි බිත්ති ලිහිල් වී සිස්ටොලික් හා ඩයස්ටොලික් පීඩනය පහත වැටේ."),
        q("දිනපතා ක්‍රියාශීලී ව්‍යායාමවල යෙදීමෙන් රුධිරයේ කොලෙස්ටරෝල් සංයුතියට සිදුවන හිතකර වෙනස කුමක්ද?", "හිතකර HDL කොලෙස්ටරෝල් වැඩි වී අහිතකර LDL කොලෙස්ටරෝල් සහ ට්‍රයිග්ලිසරයිඩ අඩුවීම", "අහිතකර LDL කොලෙස්ටරෝල් අධික ලෙස වැඩිවීම", "සියලුම ලිපිඩ ශුන්‍ය වීම", "කොලෙස්ටරෝල්වලට කිසිදු බලපෑමක් නොවීම", "HDL මගින් රුධිර නාලවල ඇති අතිරික්ත මේදය අක්මාව වෙත ගෙන ගොස් හෘදයාබාධ වළක්වයි."),
        q("ව්‍යායාම මගින් මොළයේ එන්ඩොෆින් (Endorphins) හෝමෝනය නිදහස් වීම නිසා ලැබෙන මානසික ප්‍රතිඵලය කුමක්ද?", "මානසික ආතතිය හා විෂාදය දුරු වී සතුට හා ප්‍රබෝධය ඇතිවීම", "මතක ශක්තිය ක්ෂය වීම", "තරහව වැඩිවීම", "නින්ද නොයාම", "එන්ඩොෆින් 'සතුටු හෝමෝනය' ලෙස හඳුන්වන අතර එය ස්වාභාවික වේදනා නාශකයක් ලෙසද ක්‍රියා කරයි."),
        q("ක්‍රීඩා පුහුණු සැලැස්මක 'පරිමාව' (Volume) සහ 'තීව්‍රතාව' (Intensity) අතර සාමාන්‍යයෙන් පවතින සම්බන්ධතාව කුමක්ද?", "ප්‍රතිලෝම සම්බන්ධතාවකි (තීව්‍රතාව වැඩි වන විට පරිමාව අඩු විය යුතුය)", "අනුලෝම සම්බන්ධතාවකි (දෙකම එකවර උපරිම විය යුතුය)", "කිසිදු සම්බන්ධයක් නැත", "නියත අගයකි", "අධික තීව්‍රතාවයකින් පුහුණු වන විට තෙහෙට්ටුව ඉක්මනින් එන බැවින් කාලය හෝ වාර ගණන (පරිමාව) අඩු කළ යුතුය."),
        q("සතියකට දින 3ක් ව්‍යායාම කරන සාමාන්‍ය පුද්ගලයෙකුට දින සැලසුම් කිරීමේදී වඩාත් සුදුසු ක්‍රමය කුමක්ද?", "දිනක් හැර දිනක් ව්‍යායාම කර අතරමැද දිනවල විවේකය ලබාගැනීම", "සිකුරාදා, සෙනසුරාදා, ඉරිදා එක දිගට කර ඉතිරි දින 4ම නිදාගැනීම", "එක් දිනකින් සියල්ල අවසන් කිරීම", "දිනපතා පැය 5ක් කිරීම", "දිනක් හැර දිනක් (උදා. සඳුදා, බදාදා, සිකුරාදා) ව්‍යායාම කිරීමෙන් පේශි යථා තත්ත්වයට පත්වීමට ප්‍රමාණවත් කාලය ලැබේ."),
        q("ක්‍රීඩකයෙකුගේ යෝග්‍යතා පරීක්ෂණයක් පැවැත්වීමේදී පරීක්ෂණ උපකරණ සම්මත මට්ටමින් ක්‍රමාංකනය (Calibration) කර තිබීම වැදගත් වන්නේ ඇයි?", "ලබාගන්නා දත්තවල නිරවද්‍යතාව සහ සාධාරණත්වය තහවුරු කිරීමට", "පරීක්ෂණය ඉක්මනින් අවසන් කිරීමට", "උපකරණ අලංකාරව තබා ගැනීමට", "ශිෂ්‍යයන් බිය ගැන්වීමට", "අක්‍රමවත් උපකරණ මගින් වැරදි දත්ත ලැබෙන අතර යෝග්‍යතා තක්සේරුව නිවැරදි නොවේ."),
        q("පාසල් ශාරීරික අධ්‍යාපන විෂයෙහි යෝග්‍යතා පරීක්ෂණයක් පැවැත්වීමට පෙර ශාරීරික අධ්‍යාපන ගුරුවරයා විසින් අනිවාර්යයෙන් කළ යුතු දෙය කුමක්ද?", "සිසුන්ට පරීක්ෂණ නිවැරදිව ආදර්ශනය කර පෙන්වීම සහ ශරීරය හොඳින් රත් කරවීම", "කිසිදු පැහැදිලි කිරීමකින් තොරව කෙළින්ම පරීක්ෂණය ඇරඹීම", "ශරීරය රත් කිරීම තහනම් කිරීම", "දුර්වල ළමුන් ඉවත් කිරීම", "නිවැරදි තාක්ෂණය කියාදීමෙන් අනතුරු වැළකී නිවැරදි ප්‍රතිඵල ලැබේ."),
        q("ක්‍රීඩාවේදී හෘද ස්වසන යෝග්‍යතාව ඉහළ නැංවීමට වඩාත් සුදුසු අඛණ්ඩ ධාවන වේගය තීරණය කළ හැක්කේ කුමන සරල ක්‍රමවේදයෙන්ද?", "කතා කිරීමේ පරීක්ෂණය (Talk Test - හති නොදමා කෙටි වාක්‍ය කතා කළ හැකි වේගය)", "හුස්ම නොගෙන දිවීම", "කෑගසමින් දිවීම", "ඇස් පියාගෙන දිවීම", "සවායු කලාපයේදී පුද්ගලයාට අපහසුවකින් තොරව වාක්‍ය කිහිපයක් කතා කළ හැක."),
        q("ක්‍රීඩා පුහුණුව අවසානයේ සිසිල් වීමේදී (Cool-down) ස්ථිතික දිගැදුම් කිරීමෙන් වැළකෙන ප්‍රධාන අපහසුතාව කුමක්ද?", "පේශි තදවීම, මාංශපේශී පෙරළීම (Cramps) සහ සන්ධි වේදනාව", "ශරීර උෂ්ණත්වය ඉහළ යාම", "රුධිරය කැටි ගැසීම", "බඩගින්න ඇතිවීම", "දිගැදුම් මගින් කෙටි වූ මාංශපේශී නැවත ඒවායේ සාමාන්‍ය දිගට ලිහිල් කර ලේ ගමන යහපත් කරයි."),
        q("හෘද ස්වසන විඳදරාගැනීමේ පරීක්ෂණයක් වන බීප් පරීක්ෂණයේදී (Beep Test) ශබ්ද සංඥා අතර කාල පරතරයට සිදුවන්නේ කුමක්ද?", "එක් එක් මට්ටම (Level) ඉහළ යත්ම ශබ්ද අතර කාලය අඩුවී ධාවන වේගය වැඩිවේ", "ශබ්ද අතර කාලය වැඩිවේ", "කාලය නොවෙනස්ව පවතී", "ශබ්දය නැතිවී යයි", "මට්ටමෙන් මට්ටමට බීප් ශබ්දය වේගවත් වන බැවින් ක්‍රීඩකයාට තම උපරිම වේගය තෙක් දිවීමට සිදුවේ."),
        q("ක්‍රීඩා පුහුණුවකදී 'ශක්තිජනක පද්ධතිය' (Power) ඉලක්ක කරගත් පුහුණුවකදී භාවිත කරන විවේක කාලය කුමන මට්ටමක තිබිය යුතුද?", "පූර්ණ සුවය ලැබෙන තෙක් දිගු විවේක කාලයක් (මිනිත්තු 2 සිට 5 දක්වා)", "තත්පර 5ක විවේකයක් පමණි", "කිසිසේත් විවේකයක් නොමැතිව", "පැය 1ක විවේකයක්", "උපරිම ජවය මුදාහැරීමට නම් ATP-PCr පද්ධතිය 100% ක් නැවත පිරෙන තෙක් මිනිත්තු 3-5ක විවේකයක් අවශ්‍ය වේ."),
        q("යෝග්‍යතා සංවර්ධනයේදී 'ක්‍රියාකාරී ඉරියව් පුහුණුව' (Postural Training) මගින් පුද්ගලයෙකුට ලැබෙන දිගුකාලීන වාසිය කුමක්ද?", "කොඳු ඇට පෙළ ආශ්‍රිත ආබාධ වළක්වා සිරුරේ අලංකාරය හා ක්‍රියාකාරී කාර්යක්ෂමතාව රැකදීම", "ශරීර බර අඩු වීම පමණි", "උස ක්ෂණිකව වැඩිවීම", "පෙනීම තියුණු වීම", "නිවැරදි ඉරියව් පුහුණුව මගින් කශේරුකා මත ඇතිවන අනවශ්‍ය ආතතිය සම්පූර්ණයෙන්ම ඉවත් කරයි."),
        q("පාසල් ක්‍රීඩකයෙකු තම ශාරීරික යෝග්‍යතාවය ස්වයං-ඇගයීමකට ලක්කිරීමේ ඇති ප්‍රධානතම මනෝවිද්‍යාත්මක වාසිය කුමක්ද?", "තම දක්ෂතා පිළිබඳ ආත්ම විශ්වාසය සහ අභිප්‍රේරණය (Motivation) ඉහළ යාම", "අන් අයට වඩා උසස් යැයි අහංකාර වීම", "පුහුණුවීම් නතර කිරීම", "කම්මැලි වීම", "තමන් ක්‍රමයෙන් දියුණු වන බව දකින විට ක්‍රීඩකයා තුළ පුහුණුව සඳහා දැඩි උනන්දුවක් හා කැපවීමක් ඇතිවේ."),
        q("ශාරීරික අක්‍රියතාවය සහ ව්‍යායාම නොකිරීම හේතුවෙන් හටගන්නා රෝග සමූහය පොදුවේ හඳුන්වන්නේ කෙසේද?", "අක්‍රියතා රෝග (Hypokinetic Diseases)", "බෝවන රෝග", "ප්‍රවේණික රෝග", "ක්ෂුද්‍රජීවී ආසාදන", "ශාරීරික ක්‍රියාකාරකම් අඩුවීම නිසා හටගන්නා හෘද රෝග, දියවැඩියාව, ස්ථූලතාව හයිපොකයිනෙටික් රෝග ලෙස හැඳින්වේ."),
        q("පහළ සිරුරේ කලවා (ක්වාඩ්‍රිසෙප්ස්) සහ තට්ටම් (ග්ලූටියස්) පේශි ශක්තිමත් කරන මූලික ශරීර බර ව්‍යායාමය කුමක්ද?", "ස්කොට්ස් හෙවත් දණ නැමීමේ ව්‍යායාමය (Squats)", "පුෂ්-අප්ස්", "පුල්-අප්ස්", "ප්ලෑන්ක්", "ස්කොට්ස් මගින් පාදවල ප්‍රධාන මාංශපේශී සහ ශ්‍රෝණි කලාපය විශිෂ්ට ලෙස ශක්තිමත් වේ."),
        q("පපුවේ ප්‍රධාන පේශිය (Pectoralis major) සහ උරහිස් ඉදිරිපස පේශි ශක්තිමත් කරන සම්මත බර පුහුණු ව්‍යායාමය කුමක්ද?", "බෙන්ච් ප්‍රෙස් ව්‍යායාමය (Bench Press)", "ඩෙඩ්ලිෆ්ට්", "ලෙග් ප්‍රෙස්", "කෆ් රේසස්", "බෙන්ච් එකක් මත වැතිර බාබෙල් එකක් පපුවේ සිට ඉහළට තල්ලු කිරීමෙන් පපුව සහ ට්‍රයිසෙප්ස් ශක්තිමත් වේ."),
        q("ශරීරයේ පසුපස දාමය (හැම්ස්ට්‍රිං, ග්ලූටියස් සහ කොන්දේ ඉරෙක්ටර් ස්පයිනේ) සම්පූර්ණයෙන්ම ශක්තිමත් කරන මූලික බර එසවීමේ ව්‍යායාමය කුමක්ද?", "ඩෙඩ්ලිෆ්ට් ව්‍යායාමය (Deadlift)", "බයිසෙප්ස් කර්ල්", "පුෂ්-අප්ස්", "කර්ල්-අප්ස්", "බිම ඇති බරක් කොන්ද කෙළින් තබාගෙන එසවීම මගින් මුළු ශරීරයේම ශක්තිය වර්ධනය වේ."),
        q("පිටුපස පිහිටි ලැටිසිමස් ඩෝසි (Latissimus dorsi) පේශිය සහ අතේ ද්විශීර්ෂික (බයිසෙප්ස්) පේශිය ශක්තිමත් කරන තිරස් තීරුවක එල්ලී සිදුකරන ව්‍යායාමය කුමක්ද?", "පුල්-අප්ස් හෙවත් චින්-අප්ස් (Pull-ups / Chin-ups)", "පුෂ්-අප්ස්", "ස්කොට්ස්", "ප්ලෑන්ක්", "තිරස් බාර් එකක එල්ලී මුළු ශරීරයම ඉහළට ඇදීමෙන් පිටුපස හා බාහු පේශිවල ශක්තිය මනාව වර්ධනය වේ."),
        q("උරහිස්වල ඩෙල්ටොයිඩ් පේශිය ශක්තිමත් කිරීම සඳහා බර හිසට ඉහළින් ඔසවන ව්‍යායාමය කුමක්ද?", "ඕවර්හෙඩ් ප්‍රෙස් හෙවත් ෂෝල්ඩර් ප්‍රෙස් (Overhead Press)", "බෙන්ච් ප්‍රෙස්", "ස්කොට්ස්", "කර්ල්-අප්ස්", "බර උරහිස් මට්ටමේ සිට කෙළින්ම හිසට ඉහළට එසවීමෙන් උරහිස් හා ට්‍රයිසෙප්ස් පේශි ශක්තිමත් වේ."),
        q("පාදවල සමබරතාවය, සම්බන්ධීකරණය සහ එක් එක් පාදයේ වෙන වෙනම ශක්තිය වර්ධනය කරන ඉදිරියට පියවර තබා දණ නමන ව්‍යායාමය කුමක්ද?", "ලන්ජස් ව්‍යායාමය (Lunges)", "පුෂ්-අප්ස්", "ප්ලෑන්ක්", "බෙන්ච් ප්‍රෙස්", "එක් පාදයක් ඉදිරියට තබා දණහිස අංශක 90ට නැවීමෙන් කලවා හා තට්ටම් පේශි ක්‍රමවත්ව ශක්තිමත් වේ."),
        q("කෙණ්ඩේ පිහිටි ගැස්ට්‍රොක්නීactionමියස් සහ සෝලියස් පේශි ශක්තිමත් කිරීම සඳහා විලුඹ එසවීමේ ව්‍යායාමය කුමක්ද?", "කෆ් රේසස් (Calf Raises)", "ස්කොට්ස්", "ලන්ජස්", "ඩෙඩ්ලිෆ්ට්", "පයේ ඇඟිලි තුඩු මතින් විලුඹ ඉහළට එසවීමෙන් කෙණ්ඩ පේශිවල ශක්තිය හා ජවය වැඩිවේ."),
        q("මීටර් 100 කෙටි දුර ධාවකයෙකුට (Sprinter) වඩාත්ම තීරණාත්මක වන කුසලතා සම්බන්ධ යෝග්‍යතා සංඝටක ත්‍රිත්වය කුමක්ද?", "ප්‍රතිචාර කාලය, පුපුරන සුලු ජවය සහ උපරිම වේගය", "හෘද ස්වසන විඳදරාගැනීම පමණි", "නම්‍යශීලීතාව පමණි", "ස්ථිතික සමබරතාව පමණි", "ආරම්භක වෙඩි හඬට ප්‍රතිචාර දැක්වීම, කුට්ටියෙන් පැනීමේ ජවය සහ උපරිම වේගයෙන් දිවීම කෙටි දුර ධාවනයට අත්‍යවශ්‍ය වේ."),
        q("මැරතන් ධාවකයෙකුට ජයග්‍රහණය සඳහා අත්‍යවශ්‍යම වන ප්‍රධානතම සෞඛ්‍ය සම්බන්ධ යෝග්‍යතා සංඝටකය කුමක්ද?", "හෘද ස්වසන විඳදරාගැනීම (Cardiorespiratory Endurance)", "උපරිම පේශි ශක්තිය", "ප්‍රතිචාර කාලය", "කඩිසරතාව පමණි", "පැය 2කට අධික කාලයක් එක දිගට ධාවනය කිරීමට ඉහළ සවායු ධාරිතාවක් සහ හෘද විඳදරාගැනීමක් අවශ්‍ය වේ."),
        q("ජිම්නාස්ටික් ක්‍රීඩකයෙකුට (Gymnast) සංකීර්ණ චලනයන් සාර්ථකව සිදුකිරීමට අත්‍යවශ්‍යම වන යෝග්‍යතා සංඝටක මොනවාද?", "නම්‍යශීලීතාව, සමබරතාව සහ පේශි ශක්තිය", "අධික ශරීර බර", "ප්‍රතිචාර කාලය පමණි", "දිගු දුර විඳදරාගැනීම පමණි", "ශරීරය විවිධ කෝණවලට නැවීමට නම්‍යශීලීතාවද කූරු මත සමබරව සිටීමට ශක්තිය හා සමබරතාවද අත්‍යවශ්‍ය වේ."),
        q("පාපන්දු ක්‍රීඩකයෙකුට (Footballer) පන්දුව රැගෙන ප්‍රතිවාදීන් මඟහැර දිවීමට වඩාත්ම උපකාරී වන කුසලතා සංඝටකය කුමක්ද?", "කඩිසරතාව සහ ඇස්-පාද සමායෝජනය", "ස්ථිතික සමබරතාව පමණි", "උපරිම අත් ශක්තිය", "නිෂ්ක්‍රීය නම්‍යශීලීතාව", "ශරීරයේ සමබරතාව රැකගෙන වේගයෙන් දිශාව මාරු කිරීමට සහ පන්දුව නිවැරදිව පාලනයට කඩිසරතාව හා සමායෝජනය අවශ්‍ය වේ."),
        q("යගුලිය දැමීම, කවපෙත්ත විසිකිරීම වැනි විසිකිරීමේ ඉසව් සඳහා මූලිකවම අවශ්‍ය වන යෝග්‍යතා සංඝටකය කුමක්ද?", "පුපුරන සුලු මාංශපේශී ජවය (Explosive Muscular Power)", "හෘද ස්වසන විඳදරාගැනීම", "ස්ථිතික නම්‍යශීලීතාව", "ප්‍රතිචාර කාලය පමණි", "කෙටි තත්පර ගණනකදී මුළු ශරීරයේම බලය හා වේගය උපරිමයෙන් මුදාහැරීම විසිකිරීමේ ඉසව්වල මූලික අවශ්‍යතාවයි."),
        q("බැඩ්මින්ටන් සහ මේසපන්දු ක්‍රීඩකයන්ට ප්‍රතිවාදියා එවන වේගවත් පහරවලට සාර්ථකව මුහුණ දීමට අත්‍යවශ්‍ය කුසලතාව කුමක්ද?", "ක්ෂණික ප්‍රතිචාර කාලය සහ ඇස්-අත් සමායෝජනය", "අධික බර එසවීමේ ශක්තිය", "මැරතන් විඳදරාගැනීම", "ස්ථිතික ඉරියව්ව", "පන්දුව හෝ පිහාටුව ක්ෂණිකව දැක නිවැරදිව පිත්තෙන් පහරදීමට ප්‍රතිචාර කාලය සහ සමායෝජනය තීරණාත්මක වේ."),
        q("ළමුන් සහ යෞවනයන් දිනපතා රූපවාහිනී, පරිගණක සහ ජංගම දුරකථන තිර ඉදිරිපිට ගත කරන අක්‍රිය කාලය (Screen Time) කොපමණකට සීමා කළ යුතුද?", "දිනකට පැය 2කට වඩා අඩුවෙන්", "දිනකට පැය 8ක්", "දිනකට පැය 12ක්", "සීමා කිරීමක් අවශ්‍ය නැත", "අධික screen time මගින් ළමා ස්ථූලතාවය, පෙනීමේ ආබාධ හා ඉරියව් දෝෂ හටගනී."),
        q("පාසලට හෝ රැකියා ස්ථානයට යාමේදී බස් රථ වෙනුවට පයින් ඇවිදීම හෝ පාපැදි පැදීම මගින් දෛනික යෝග්‍යතාව නංවන සංකල්පය කුමක්ද?", "ක්‍රියාශීලී ප්‍රවාහනය (Active Transport)", "අක්‍රිය ප්‍රවාහනය", "විවේකී ප්‍රවාහනය", "වායුගෝලීය ප්‍රවාහනය", "දෛනික ජීවිතයට ඇවිදීම හා පාපැදිය එක්කර ගැනීමෙන් හෘද රෝග අවදානම 30% කින් පමණ අඩු වේ."),
        q("යෝග්‍යතා පුහුණුවකදී හෘද ස්පන්දන වේගය මැනිය හැකි ශරීරයේ බාහිරින් වඩාත් පැහැදිලිව ස්පර්ශ වන ප්‍රධාන ස්ථාන දෙක මොනවාද?", "මැණික්කටුවේ රේඩියල් ධමනිය සහ බෙල්ලේ කැරොටයිඩ් ධමනිය", "නළල සහ පපුව මැද", "දණහිස පිටුපස පමණි", "පාදයේ ඇඟිලි තුඩු", "මැණික්කටුවේ මාපටැඟිල්ල පාමුල රේඩියල් ධමනිය මත ඇඟිලි තුඩු තබා ස්පන්දනය පහසුවෙන් ගණනය කළ හැක."),
        q("ස්පන්දන වේගය මැනීමේදී මාපටැඟිල්ල (Thumb) භාවිත නොකළ යුත්තේ කුමන හේතුව නිසාද?", "මාපටැඟිල්ල තුළද ප්‍රබල ස්වාභාවික ස්පන්දනයක් ඇති බැවින් වැරදි අගයක් ලැබිය හැකි නිසා", "මාපටැඟිල්ල කෙටි වැඩි නිසා", "මාපටැඟිල්ලට රුධිරය නොඑන නිසා", "එය අපිරිසිදු විය හැකි නිසා", "ස්පන්දනය මැනිය යුත්තේ දබරැඟිල්ල සහ මැදඟිල්ල යොදාගනිමිනි."),
        q("ක්‍රීඩා පුහුණුවකදී දහඩිය දැමීම නිසා ශරීරයෙන් ඉවත් වන ප්‍රධාන ඛනිජ ලවණ මොනවාද?", "සෝඩියම්, ක්ලෝරයිඩ් සහ පොටෑසියම්", "යකඩ සහ කැල්සියම් පමණි", "අයඩීන් පමණි", "සින්ක් සහ තඹ පමණි", "දහඩිය මගින් ලවණ ඉවත් වන බැවින් දීර්ඝ ව්‍යායාමවලදී ඉලෙක්ට්‍රොලයිට සහිත පාන ලබාගත යුතුය."),
        q("ව්‍යායාමයකින් පසු ක්ෂය වූ පේශි ග්ලයිකොජන් සංචිත වේගයෙන් ප්‍රතිස්ථාපනය වීමට වඩාත්ම සුදුසු කාල කවුළුව (Anabolic Window) කුමක්ද?", "ව්‍යායාමය අවසන් වී මිනිත්තු 30 සිට 45 ඇතුළත", "ව්‍යායාමයෙන් පැය 24කට පසු", "දින 3කට පසු", "ව්‍යායාමයට දිනකට පෙර", "ව්‍යායාමයෙන් පසු මුල් මිනිත්තු 45 තුළ පේශිවල ඉන්සියුලින් සංවේදීතාව උපරිම බැවින් කාබෝහයිඩ්‍රේට් හා ප්‍රෝටීන් පහසුවෙන් අවශෝෂණය වේ."),
        q("මාංශපේශී ගොඩනැගීමේ පුහුණුවක (Bodybuilding) නිරත වන ක්‍රීඩකයෙකුට දිනකට අවශ්‍ය වන ප්‍රෝටීන් ප්‍රමාණය ශරීර බර කිලෝග්‍රෑමයකට කොපමණද?", "ශරීර බර කිලෝග්‍රෑමයකට ග්‍රෑම් 1.2 සිට 2.0 දක්වා", "ශරීර බර කිලෝග්‍රෑමයකට ග්‍රෑම් 10ක්", "ශරීර බර කිලෝග්‍රෑමයකට ග්‍රෑම් 0.1ක්", "ප්‍රෝටීන් අවශ්‍ය නොවේ", "සාමාන්‍ය පුද්ගලයෙකුට 0.8 g/kg ප්‍රමාණවත් වුවද බර පුහුණු ක්‍රීඩකයන්ට පේශි අලුත්වැඩියාවට 1.2-2.0 g/kg අවශ්‍ය වේ."),
        q("ශරීරයේ කඳ කොටස (Core) ශක්තිමත් කිරීම මගින් ක්‍රීඩකයෙකුට ලැබෙන මූලිකම වාසිය කුමක්ද?", "පාදවල සිට ඉහළ සිරුරට බලය කාර්යක්ෂමව සම්ප්‍රේෂණය කිරීම සහ ශරීර ස්ථාවරත්වය සුරැකීම", "ශරීරයේ උස වැඩිවීම පමණි", "පෙනීම වැඩිවීම", "නින්ද අඩු වීම", "ප්‍රබල Core පේශි පද්ධතියක් මගින් පයින් ගැසීම, විසි කිරීම, දිවීම වැනි සියලු චලනවල කාර්යක්ෂමතාව ඉහළ නංවයි."),
        q("බර එසවීමේදී පිටකොන්ද වක්‍ර නොකර (කුද නොගසා) කොඳු ඇට පෙළ ස්වාභාවික සෘජු ඉරියව්වක තබාගත යුත්තේ ඇයි?", "අන්තර් කශේරුකා මඬල (Intervertebral Discs) මත ඇතිවන පීඩනය සමබර කර කශේරුකා ලිස්සා යාම වැළැක්වීමට", "බර සැහැල්ලු වන බැවින්", "වේගයෙන් එසවිය හැකි බැවින්", "පපුව කුඩා වන බැවින්", "කොන්ද වක්‍ර කර බර එසවීමේදී කශේරුකා අතර මඬල පිපිරීම හෝ ස්නායු තදවීම සිදුවිය හැක."),
        q("ක්‍රීඩා පුහුණුවකදී 'ප්ලේටෝ' (Plateau) හෙවත් එකතැන පල්වීමේ තත්ත්වය බිඳහෙළීමට පුහුණුකරු විසින් ගත යුතු පියවර කුමක්ද?", "පුහුණු ක්‍රම, තීව්‍රතාව හෝ අභ්‍යාස මාරු කරමින් නව උත්තේජනයක් ලබාදීම", "පුහුණුවීම් සදහටම අත්හැර දැමීම", "එකම අභ්‍යාසය තව තවත් පැය ගණනක් කිරීම", "ආහාර නොගෙන සිටීම", "විවිධත්වයේ මූලධර්මය යොදාගනිමින් ශරීරයට නව අනුවර්තනයක් සඳහා අභියෝග කළ යුතුය."),
        q("ශාරීරික යෝග්‍යතාවය පවත්වා ගැනීමෙන් වයස්ගත වීමේදී ඇතිවන ඩිමෙන්ෂියාව සහ ඇල්සයිමර් වැනි මොළයේ රෝග අවදානම අඩුවන්නේ ඇයි?", "මොළයට ඔක්සිජන් සහ රුධිර සැපයුම වැඩි වී නව ස්නායු සබඳතා වර්ධනය වීම උත්තේජනය වන බැවින්", "හිස්කබල ඝන වන බැවින්", "මොළයේ සෛල විනාශ වන බැවින්", "නින්ද සම්පූර්ණයෙන් නැතිවන බැවින්", "ව්‍යායාම මගින් මොළයේ හිපොකැම්පස් ප්‍රදේශයේ සෛල වර්ධනය උත්තේජනය වී මතකය සුරකියි."),
        q("යෝග්‍යතා පුහුණුවකදී සන්ධියක නම්‍යශීලීතාව වැඩි කර ගැනීමට සුදුසුම කාලය කුමක්ද?", "ශරීරය හොඳින් රත් වූ පසු හෝ ප්‍රධාන පුහුණු සැසිය අවසානයේ සිසිල් වීමේදී", "උදෑසන අවදි වූ වහාම ඇඳ උඩදීම", "ශරීරය සීතලව තිබියදී එකවරම", "වෙහෙසට පත්වීමට පෙර සීතලෙන්", "මාංශපේශී උණුසුම්ව පවතින විට ඒවායේ ප්‍රත්‍යාස්ථතාව ඉහළ බැවින් ආබාධයකින් තොරව උපරිමව දිගහැරිය හැක."),
        q("අධික වේගයෙන් පාද සහ දෑත් ගැස්සීම් සහිතව සිදුකරන 'බැලස්ටික් දිගැදුම්' (Ballistic Stretching) සාමාන්‍ය අයට නිර්දේශ නොකරන්නේ ඇයි?", "පේශි ඉරී යාමේ සහ බන්ධනී ආබාධ ඇතිවීමේ ඉහළ අවදානමක් පවතින බැවින්", "එයින් නම්‍යශීලීතාව වැඩි නොවන බැවින්", "කාලය අපතේ යන බැවින්", "එය ඉතා පහසු බැවින්", "ගැස්සීම් සහිත දිගැදුම් මගින් පේශි ආතති ප්‍රතිචාරය (Stretch Reflex) උත්තේජනය වී පේශිය අනතුරුදායක ලෙස හැකිලෙයි."),
        q("නිරෝගී වැඩිහිටියෙකු තම හෘද සෞඛ්‍යය ආරක්ෂා කර ගැනීම සඳහා දිනකට අවම වශයෙන් පියවර කීයක් ඇවිදිය යුතු බව පොදුවේ පිළිගැනේද?", "දිනකට පියවර 8,000 සිට 10,000 දක්වා", "දිනකට පියවර 500ක් පමණි", "දිනකට පියවර 50,000ක්", "දිනකට පියවර 50ක්", "දිනකට පියවර 10,000ක් ඇවිදීම මගින් දෛනික ක්‍රියාශීලීභාවය තහවුරු වී නිදන්ගත රෝග වළකී."),
        q("පාසල් ශාරීරික අධ්‍යාපන විෂය මාලාවට අනුව ශාරීරික යෝග්‍යතා පරීක්ෂණ වර්ෂයකට අවම වශයෙන් වාර කීයක් පැවැත්විය යුතුද?", "වසරකට දෙවරක් (වසර ආරම්භයේ සහ වසර අවසානයේ)", "වසර 5කට එක් වරක්", "සෑම දිනකම", "කිසි විටෙකත් නොපැවැත්විය යුතුය", "වසර ආරම්භයේ මූලික මට්ටම හඳුනාගෙන වසර අවසානයේ ප්‍රගතිය ඇගයීම සම්මත පිළිවෙතයි."),
        q("ක්‍රීඩා පුහුණුවකදී 'සමමිතික' (Isometric) ව්‍යායාම සඳහා හොඳම ප්‍රායෝගික නිදසුනක් කුමක්ද?", "ප්ලෑන්ක් (Plank) සහ බිත්තියට හේත්තු වී වාඩිවී සිටීම (Wall Sit)", "මීටර් 100 ධාවනය", "කඹ පැනීම", "පිහිනීම", "සන්ධි චලනය නොවී පේශි ආතතිය පමණක් රඳවාගෙන සිටින ව්‍යායාම සමමිතික වේ."),
        q("පාදවල පේශි විඳදරාගැනීම සහ හෘද ස්වසන යෝග්‍යතාව එකවර වර්ධනය කරන සරල උපකරණයක් භාවිත කරන ව්‍යායාමය කුමක්ද?", "කඹ පැනීම (Rope Skipping)", "බර එසවීම පමණි", "ස්ටෝක් පරීක්ෂණය", "සිට් ඇන්ඩ් රීච්", "කඹ පැනීම මගින් පාදවල කඩිසරතාව, සමායෝජනය සහ සවායු ශක්තිය විශිෂ්ට ලෙස දියුණු වේ."),
        q("ශරීරයේ ඉහළ කඳ, පිටකොන්ද සහ බඩවැල් ආශ්‍රිත මාංශපේශී ලිහිල් කර නම්‍යශීලීතාව ලබාදෙන සාම්ප්‍රදායික ව්‍යායාම ක්‍රමය කුමක්ද?", "යෝග සහ ආසන අභ්‍යාස (Yoga Asanas)", "බර එසවීම", "කෙටි දුර ධාවනය", "යගුලිය දැමීම", "යෝග අභ්‍යාස මගින් ශාරීරික නම්‍යශීලීතාව, සමබරතාව මෙන්ම මානසික ඒකාග්‍රතාවද වර්ධනය කරයි."),
        q("ක්‍රීඩකයෙකුට තරගයක් අතරතුර ක්ෂණිකව 'මාංශපේශී පෙරළීමක්' (Muscle Cramp) ඇතිවීමට බලපාන ප්‍රධාන සාධක දෙක මොනවාද?", "විජලනය වීම සහ ඉලෙක්ට්‍රොලයිට ලවණ (සෝඩියම්, පොටෑසියම්) ක්ෂය වීම", "අධික ලෙස ජලය පානය කිරීම", "සීතල වැඩිවීම පමණි", "නින්ද වැඩිවීම", "දැඩි තෙහෙට්ටුව සහ ලවණ ඌනතාවය නිසා ස්නායු-පේශි පාලනය බිඳවැටී පේශිය තදින් හැකිලී පවතී."),
        q("මාංශපේශී පෙරළීමක් (Cramp) ඇති වූ වහාම කළ යුතු ක්ෂණික ප්‍රථමාධාරය කුමක්ද?", "අදාළ පේශිය සෙමින් විරුද්ධ දිශාවට දිගහැර (Stretch) මෘදු ලෙස සම්බාහනය කිරීම", "පේශියට තදින් පහරදීම", "තව තවත් වේගයෙන් දිවීම", "අයිස් කැට ගිලීම", "පෙරළුණු පේශිය සෙමින් දිගහැරීම මගින් පේශි හැකිලීම ලිහිල් වී වේදනාව සමනය වේ."),
        q("ශාරීරික යෝග්‍යතාවය ඉහළ පුද්ගලයෙකුගේ ප්‍රතිශක්තිකරණ පද්ධතියට ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "සුදු රුධිර සෛල සංසරණය කාර්යක්ෂම වී සෙම්ප්‍රතිශ්‍යාව වැනි සුළු ආසාදනවලට ඔරොත්තු දීමේ හැකියාව වැඩිවීම", "කිසිදා කිසිදු ලෙඩක් නොහැදීම", "රුධිර සෛල විනාශ වීම", "ප්‍රතිදේහ නිපදවීම නතර වීම", "මධ්‍යම ප්‍රමාණයේ දෛනික ව්‍යායාම මගින් ප්‍රතිශක්තිකරණ සෛලවල ක්‍රියාකාරිත්වය නිරන්තරයෙන් අවදි කර තබයි."),
        q("ව්‍යායාමයකදී අධික ලෙස දහඩිය දැමූ විට ඇඳුම් තෝරාගැනීමේදී වඩාත් සැලකිලිමත් විය යුතු කරුණ කුමක්ද?", "දහඩිය පහසුවෙන් උරාගන්නා සහ වාතාශ්‍රය ලැබෙන සැහැල්ලු කපු ඇඳුම් භාවිතය", "තද කළු පැහැති ඝන ඇඳුම් ඇඳීම", "ප්ලාස්ටික් රෙදි භාවිතය", "ශීත ඍතු ජැකට් පැළඳීම", "වාතාශ්‍රය සහිත ඇඳුම් මගින් දහඩිය වාෂ්පීභවනය පහසු කර තාප කම්පනය වළක්වයි."),
        q("ක්‍රීඩාවේදී 'අත්-පාද වේගය' (Footwork and Hand Speed) දියුණු කිරීම සඳහා භාවිත කරන විශේෂිත උපකරණයක් කුමක්ද?", "කඩිසරතා ඉණිමඟ (Agility Ladder)", "ස්පයිරෝමීටරය", "බර එසවීමේ බාබෙල්", "ස්ටෙතස්කෝපය", "Agility ladder මගින් පාද ඉක්මනින් හා නිවැරදිව තැබීමේ ස්නායු-පේශි සමායෝජනය දියුණු කරයි."),
        q("ක්‍රීඩකයෙකුගේ උපරිම ධාවන වේගය (Maximum Sprint Speed) තීරණය වන ප්‍රධාන ජෛව යාන්ත්‍රික සාධක දෙක මොනවාද?", "පියවරෙහි දිග (Stride Length) සහ පියවර තැබීමේ සීඝ්‍රතාව (Stride Frequency)", "ක්‍රීඩාංගණයේ වර්ණය", "සපත්තු වල මිල", "ශරීරයේ උස පමණි", "වේගය = පියවර දිග × පියවර සංඛ්‍යාතය වන අතර නිවැරදි තාක්ෂණය මගින් මේ දෙකම ප්‍රශස්ත කළ යුතුය."),
        q("පාසල් වියේදී නිතිපතා ශාරීරික යෝග්‍යතා ව්‍යායාමවල යෙදීමෙන් අනාගත වැඩිහිටි වියේදී ලැබෙන සමාජීය වාසිය කුමක්ද?", "යහපත් ජීවන රටාවක්, කණ්ඩායම් හැඟීමක් සහ නිරෝගී ක්‍රියාශීලී පුරවැසියෙකු බිහිවීම", "අන් අය සමග නිතර රණ්ඩු කිරීම", "හුදෙකලා වීම", "සමාජයෙන් ඈත්වීම", "ක්‍රීඩාව හා යෝග්‍යතාව තුළින් විනය, ඉවසීම සහ නායකත්ව ගුණාංග ජීවිතයට එකතු වේ."),
        q("ක්‍රීඩා පුහුණු සැසියක් නිමවීමෙන් පසු ස්නානය කිරීමට පෙර ක්‍රීඩකයෙකු විසින් කළ යුතු දේ කුමක්ද?", "දහඩිය හොඳින් වියළී ශරීර උෂ්ණත්වය සහ හෘද ස්පන්දනය සාමාන්‍ය මට්ටමට පත්වන තෙක් සුළු වේලාවක් සිටීම", "දැඩිව දහඩිය දමද්දීම වහාම ශීතල ජලයෙන් ස්නානය කිරීම", "උණුසුම් වාෂ්ප කාමරයකට යාම", "අධික ලෙස සීතල පැණිබීම බීම", "ශරීරය සිසිල් වීමට පෙර වහාම ස්නානය කිරීමෙන් රුධිර වාහිනී ක්ෂණිකව හැකිලී අහිතකර ප්‍රතික්‍රියා ඇතිවිය හැක."),
        q("ක්‍රීඩා පුහුණුවකදී තමන්ට දරාගත නොහැකි අධික පපුවේ වේදනාවක් හෝ කරකැවිල්ලක් දැනුනහොත් ක්‍රීඩකයා කළ යුත්තේ කුමක්ද?", "වහාම ව්‍යායාමය නවතා පුහුණුකරුට හෝ වෛද්‍යවරයෙකුට දැනුම් දී විවේක ගැනීම", "වේදනාව නොසලකා තව තවත් වේගයෙන් දිවීම", "හුස්ම තද කරගෙන බර එසවීම", "කිසිවෙකුට නොකියා නිහඬව සිටීම", "පපුවේ වේදනාව හෘද වාහිනී ආබාධයක පෙරනිමිත්තක් විය හැකි බැවින් වහාම නැවැත්විය යුතුය."),
        q("ක්‍රීඩා ඉතිහාසයේ යෝග්‍යතා සංවර්ධනය වෙනුවෙන් සුවිශේෂී මෙහෙවරක් කළ ශ්‍රී ලාංකික පාසල් දරුවන්ට ලබාදිය හැකි හොඳම පණිවිඩය කුමක්ද?", "ක්‍රීඩාව සහ ශාරීරික යෝග්‍යතාව අධ්‍යාපනයට බාධාවක් නොව අධ්‍යාපනික සාර්ථකත්වයට මනා පිටුවහලකි", "ක්‍රීඩා කරන විට පාඩම් කළ නොහැක", "විභාග සමයේ ක්‍රීඩා සම්පූර්ණයෙන් නැවැත්විය යුතුය", "යෝග්‍යතාව වැදගත් වන්නේ ක්‍රීඩකයන්ට පමණි", "නිරෝගී සිරුරක් තුළ පමණක් නිරෝගී මනසක් බිහිවන බැවින් අධ්‍යාපනය හා ක්‍රීඩාව සමබරව ගෙන යා යුතුය."),
        q("ක්‍රීඩා පුහුණුවකදී 'ප්‍රතිරෝධක පුහුණුවේ' (Resistance Training) ප්‍රධාන ධනාත්මක සෞඛ්‍යමය වාසියක් වන්නේ කුමක්ද?", "අස්ථි ඛනිජ ඝනත්වය වැඩි වී ඔස්ටියෝපොරෝසිස් අවදානම අඩුවීම", "රුධිර පීඩනය ඉහළ යාම පමණි", "සන්ධි ගෙවී යාම", "මාංශපේශී ක්ෂය වීම", "බර එසවීමේදී අස්ථි මත ඇතිවන යාන්ත්‍රික පීඩනය නිසා ඔස්ටියෝබ්ලාස්ට සක්‍රීය වී අස්ථි ඝනකම වැඩිවේ."),
        q("කායික ක්‍රියාකාරකම්වල යෙදෙන විට ශරීරයේ ඉන්සියුලින් හෝමෝන සංවේදීතාවට සිදුවන බලපෑම කුමක්ද?", "ඉන්සියුලින් සංවේදීතාව ඉහළ ගොස් රුධිර ග්ලූකෝස් මට්ටම වඩාත් පහසුවෙන් පාලනය වීම", "ඉන්සියුලින් සංවේදීතාව සම්පූර්ණයෙන් නැතිවීම", "රුධිර සීනි පාලනයෙන් තොර වීම", "ඉන්සියුලින් නිෂ්පාදනය නතර වීම", "ව්‍යායාම මගින් පේශි සෛලවල GLUT-4 ග්ලූකෝස් වාහක සක්‍රීය වී ඉන්සියුලින් ප්‍රතිරෝධය දුරු කරයි."),
        q("යෝග්‍යතා සංවර්ධනයේදී 'ක්‍රියාකාරී නම්‍යශීලීතාව' (Functional Flexibility) පාසල් සිසුන්ට වැදගත් වන්නේ ඇයි?", "දෛනික වැඩකටයුතුවලදී සහ ක්‍රීඩාවේදී අනතුරුදායක සන්ධි ඇදීම්වලින් තොරව නිදහසේ චලනය වීමට හැකිවන බැවින්", "පොත් බෑග් එසවීම නැවැත්වීමට", "කෙට්ටු වීමට පමණක්", "ශරීරයේ උස වැඩි නොවන නිසා", "ක්‍රියාකාරී නම්‍යශීලීතාව මගින් සිරුරේ බන්ධනී හා කණ්ඩරා නිරෝගීව හා සුනම්‍යව තබා ගනී."),
        q("දිනපතා උදෑසන හෝ සවස ශාරීරික ක්‍රියාකාරකම්වල යෙදීමෙන් රාත්‍රී නින්දට ලැබෙන යහපත් බලපෑම කුමක්ද?", "ගැඹුරු සුවදායී නින්දක් (Deep Sleep) ලැබීම සහ නින්ද නොයාමේ ගැටලු අවම වීම", "නින්ද සම්පූර්ණයෙන්ම අහිමි වීම", "නපුරු සිහින පෙනීම", "දිවා කාලයේ නිතර නිදිමත ඇතිවීම", "දෛනික ශාරීරික ක්‍රියාකාරකම් මගින් නින්දේ කාලසීමාව හා ගුණාත්මකභාවය බෙහෙවින් ඉහළ නංවයි."),
        q("ක්‍රීඩා පුහුණුවකදී 'හෘද ස්පන්දන වේග මොනිටරයක්' (Heart Rate Monitor) පැළඳීමෙන් ක්‍රීඩකයාට ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "තමන් පුහුණු වන්නේ නියමිත ඉලක්කගත හෘද ස්පන්දන කලාපය තුළදැයි තථ්‍ය කාලීනව දැනගැනීමට හැකිවීම", "වේගයෙන් දිවීමට තල්ලුවක් ලැබීම", "හෘදය ස්පන්දනය වීම නැවැත්වීම", "ඇඳුම් බර අඩු කිරීම", "හෘද මොනිටර මගින් අඩු පුහුණුව හෝ අධිපුහුණුව වළක්වා නියමිත තීව්‍රතාවයේ රැඳී සිටීමට උපකාරී වේ."),
        q("ශාරීරික යෝග්‍යතාවය ඉහළ නැංවීමේදී 'සමබර පෝෂණය' (Balanced Nutrition) සහ 'ජලනය' (Hydration) අත්‍යවශ්‍ය සාධකයක් වන්නේ ඇයි?", "ව්‍යායාම මගින් ශරීරය වැය කළ ශක්තිය හා පටක අලුත්වැඩියාව සඳහා අවශ්‍ය අමුද්‍රව්‍ය සැපයෙන්නේ ආහාරයෙන් බැවින්", "ආහාර නොමැතිව පුහුණු වීමෙන් ශක්තිය වැඩිවන බැවින්", "ජලය පානය කිරීමෙන් බර වැඩිවන බැවින්", "ආහාර මගින් ව්‍යායාමවල ප්‍රතිඵල විනාශ වන බැවින්", "නිසි පෝෂණය නොමැතිව යෝග්‍යතාව වර්ධනය කරගත නොහැකි අතර එය අධිපුහුණුවට හා ආබාධවලට මඟ පාදයි.")
    )
}
